extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale basket.tscn deve avviarsi correttamente"):
		return
	var label := find_by_class(main, "Label") as Label
	if not check("label", label != null, "Il nodo Label deve essere presente nel cesto"):
		return
	await wait_frames(2)
	check("initial_text", label.text == "Cesto | Vite: 3 | Vel: 350.0", "All'avvio il Label deve mostrare 'Cesto | Vite: 3 | Vel: 350.0', ma mostra '%s'" % label.text)
	if not check("has_set_speed", has_function(main, "set_speed"), "Lo script basket.gd deve possedere la funzione set_speed(new_speed: float)"):
		return
	call_if_exists(main, "set_speed", [420.5])
	check("updated_speed", label.text == "Cesto | Vite: 3 | Vel: 420.5", "Dopo set_speed(420.5) il Label deve mostrare 'Cesto | Vite: 3 | Vel: 420.5', ma mostra '%s'" % label.text)
	call_if_exists(main, "set_speed", 200.0)
	check("integer_speed", label.text == "Cesto | Vite: 3 | Vel: 200.0", "Con velocità 200.0 il segnaposto %%.1f deve mostrare sempre un decimale: '200.0'")

